package site.hsu.hub.file.adapter.out.persistence;import jakarta.persistence.*;import java.time.Instant;
@Entity@Table(name="file_cleanup_tasks")public class FileCleanupTaskEntity{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="file_asset_id",nullable=false)private Long fileAssetId;@Column(name="object_key",nullable=false,length=80)private String objectKey;@Column(nullable=false)private int attempts;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="last_attempt_at")private Instant lastAttemptAt;protected FileCleanupTaskEntity(){}public FileCleanupTaskEntity(Long file,String key){fileAssetId=file;objectKey=key;createdAt=Instant.now();}public Long id(){return id;}public Long fileAssetId(){return fileAssetId;}public String objectKey(){return objectKey;}public void attempted(){attempts++;lastAttemptAt=Instant.now();}}
